* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: #f5f7fa;
  color: #142033;
}

.warehouse-app {
  width: 100%;
  min-height: 100vh;
  padding: 14px;
  background: #f5f7fa;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}

.title {
  font-size: 18px;
  font-weight: 800;
  color: #142033;
}

.subtitle {
  margin-top: 3px;
  font-size: 12px;
  color: #667085;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  font-size: 11px;
  color: #475467;
}

.legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend i {
  width: 11px;
  height: 11px;
  border-radius: 3px;
  display: inline-block;
}

.legend .empty {
  background: #e7eef7;
}

.legend .assigned {
  background: #2f80ed;
}

.legend .full {
  background: #d92d20;
}

.legend .special {
  background: #12b76a;
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(320px, 0.9fr);
  gap: 12px;
}

.panel {
  background: white;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  overflow: hidden;
  min-height: 430px;
}

.panel-title {
  height: 38px;
  display: flex;
  align-items: center;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 800;
  color: #344054;
  border-bottom: 1px solid #e4e7ec;
  background: #fbfcfe;
}

.floor2d {
  position: relative;
  height: 470px;
  margin: 14px;
  border: 2px solid #243447;
  border-radius: 6px;
  background: linear-gradient(90deg, rgba(20, 32, 51, 0.05) 1px, transparent 1px), linear-gradient(rgba(20, 32, 51, 0.05) 1px, transparent 1px), #ffffff;
  background-size: 28px 28px;
  overflow: hidden;
}

.zone-label {
  position: absolute;
  left: 12px;
  top: 10px;
  font-size: 11px;
  font-weight: 800;
  color: #667085;
  text-transform: uppercase;
}

.dock {
  position: absolute;
  left: 18px;
  height: 58px;
  border: 1px solid #98a2b3;
  border-radius: 5px;
  background: #ecfdf3;
  color: #067647;
  font-size: 11px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 6px;
  cursor: pointer;
}

.dock.shipping {
  background: #fff7ed;
  color: #b54708;
}

.rack-row {
  position: absolute;
  display: flex;
  gap: 5px;
  padding: 6px;
  border-radius: 6px;
  background: rgba(36, 52, 71, 0.06);
}

.aisle-label {
  position: absolute;
  font-size: 10px;
  font-weight: 800;
  color: #667085;
  transform: rotate(-90deg);
  transform-origin: left top;
}

.bin2d {
  width: 54px;
  height: 42px;
  border-radius: 4px;
  border: 1px solid #b8c4d2;
  cursor: pointer;
  padding: 4px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.12s ease, box-shadow 0.12s ease, border-color 0.12s ease;
}

.bin2d:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(20, 32, 51, 0.16);
}

.bin2d.selected {
  outline: 3px solid #fdb022;
  outline-offset: 2px;
}

.bin2d.empty {
  background: #e7eef7;
}

.bin2d.assigned {
  background: #2f80ed;
  color: white;
  border-color: #1d5fbf;
}

.bin2d.full {
  background: #d92d20;
  color: white;
  border-color: #b42318;
}

.bin2d.special {
  background: #12b76a;
  color: white;
  border-color: #039855;
}

.bin-code {
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bin-capacity {
  font-size: 9px;
  opacity: 0.9;
  text-align: right;
}

.floor3d {
  height: 470px;
  margin: 14px;
  border-radius: 6px;
  background: linear-gradient(145deg, #edf2f7 0%, #ffffff 45%, #eef4ff 100%);
  position: relative;
  overflow: hidden;
  perspective: 900px;
  border: 1px solid #d9e2ec;
}

.scene3d {
  position: absolute;
  left: 50%;
  top: 52%;
  width: 420px;
  height: 310px;
  transform-style: preserve-3d;
  transform: translate(-50%, -50%) rotateX(58deg) rotateZ(-38deg);
}

.floor-plane {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(20, 32, 51, 0.08) 1px, transparent 1px), linear-gradient(rgba(20, 32, 51, 0.08) 1px, transparent 1px), #f8fafc;
  background-size: 36px 36px;
  border: 2px solid #98a2b3;
  transform: translateZ(-1px);
}

.rack3d {
  position: absolute;
  width: 42px;
  height: 130px;
  transform-style: preserve-3d;
  cursor: pointer;
}

.rack3d .top {
  position: absolute;
  inset: 0;
  border-radius: 4px;
  background: #2f80ed;
  border: 1px solid rgba(20, 32, 51, 0.35);
  transform: translateZ(34px);
}

.rack3d .side {
  position: absolute;
  left: 0;
  bottom: -34px;
  width: 42px;
  height: 34px;
  background: #1d5fbf;
  transform-origin: top;
  transform: rotateX(-90deg);
}

.rack3d .front {
  position: absolute;
  right: -34px;
  top: 0;
  width: 34px;
  height: 130px;
  background: #155099;
  transform-origin: left;
  transform: rotateY(90deg);
}

.rack3d.full .top {
  background: #d92d20;
}

.rack3d.full .side {
  background: #b42318;
}

.rack3d.full .front {
  background: #912018;
}

.rack3d.empty .top {
  background: #cfd8e3;
}

.rack3d.empty .side {
  background: #98a2b3;
}

.rack3d.empty .front {
  background: #667085;
}

.rack3d.special .top {
  background: #12b76a;
}

.rack3d.special .side {
  background: #039855;
}

.rack3d.special .front {
  background: #027a48;
}

.bottom {
  margin-top: 12px;
  min-height: 40px;
  border: 1px solid #d9e2ec;
  background: white;
  border-radius: 8px;
  padding: 9px 12px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.label {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
  margin-right: 8px;
  text-transform: uppercase;
}

#selectedText {
  font-size: 13px;
  font-weight: 800;
}

.debug {
  font-size: 11px;
  color: #667085;
}

.empty-state {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #667085;
  font-size: 13px;
  font-weight: 700;
}

@media (max-width: 900px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .floor2d,
  .floor3d {
    height: 420px;
  }
}

