let lastModel = {};
let lastLocations = [];

function safeText(value) {
  return String(value ?? "");
}

function byText(a, b) {
  return safeText(a).localeCompare(safeText(b), undefined, {
    numeric: true,
    sensitivity: "base"
  });
}

function statusClass(location) {
  const status = safeText(location.locationStatus).toUpperCase();

  if (Number(location.isReceivingArea || 0) === 1 || status === "RECEIVING") {
    return "special";
  }

  if (Number(location.isShippingArea || 0) === 1 || status === "SHIPPING") {
    return "special";
  }

  if (status === "FULL" || Number(location.capacityPercent || 0) >= 100) {
    return "full";
  }

  if (status === "ASSIGNED" || Number(location.productCount || 0) > 0) {
    return "assigned";
  }

  return "empty";
}

function groupedLocations(locations) {
  const result = {};

  locations.forEach(loc => {
    const aisle = safeText(loc.aisleCode || loc.zoneCode || "AREA");
    const rack = safeText(loc.rackCode || loc.locationType || "RACK");

    result[aisle] = result[aisle] || {};
    result[aisle][rack] = result[aisle][rack] || [];
    result[aisle][rack].push(loc);
  });

  return result;
}

function selectedIdFromModel(model) {
  return Number(model.selectedLocationId || model.clickedLocationId || 0);
}

function setSelected(location) {
  const selectedText = document.getElementById("selectedText");

  if (!location) {
    selectedText.innerText = "None";
    return;
  }

  selectedText.innerText = `${location.locationCode || location.code || ""} - ${location.locationName || location.name || ""}`;
}

function sendSelection(locationId) {
  if (window.appsmith && appsmith.updateModel) {
    appsmith.updateModel({
      selectedLocationId: Number(locationId),
      clickedLocationId: Number(locationId)
    });
  }

  if (window.appsmith && appsmith.triggerEvent) {
    setTimeout(() => {
      appsmith.triggerEvent("onLocationClick");
    }, 120);
  }
}

function bindClicks() {
  document.querySelectorAll("[data-location-id]").forEach(el => {
    el.onclick = function () {
      const id = Number(this.dataset.locationId || 0);
      const selected = lastLocations.find(x => Number(x.locationId || x.id) === id);

      document
        .querySelectorAll("[data-location-id]")
        .forEach(node => node.classList.remove("selected"));

      document
        .querySelectorAll(`[data-location-id="${id}"]`)
        .forEach(node => node.classList.add("selected"));

      setSelected(selected);
      sendSelection(id);

      const debugText = document.getElementById("debugText");
      debugText.innerText = `Selected location ID: ${id}`;
    };
  });
}

function render2d(locations, selectedId) {
  const floor = document.getElementById("floor2d");

  if (!locations.length) {
    floor.innerHTML = `<div class="empty-state">No warehouse locations found. Create locations first.</div>`;
    return;
  }

  const normalLocations = locations.filter(loc => {
    const type = safeText(loc.locationType).toUpperCase();
    return type !== "RECEIVING" && type !== "SHIPPING";
  });

  const receiving = locations.find(loc =>
    Number(loc.isReceivingArea || 0) === 1 ||
    safeText(loc.locationCode).toUpperCase().includes("RECEIVING")
  );

  const shipping = locations.find(loc =>
    Number(loc.isShippingArea || 0) === 1 ||
    safeText(loc.locationCode).toUpperCase().includes("SHIPPING")
  );

  const grouped = groupedLocations(normalLocations);
  const aisleKeys = Object.keys(grouped).sort(byText);

  const rackRows = [];
  const startY = 88;
  const rowGap = 78;

  aisleKeys.forEach((aisle, aisleIndex) => {
    const racks = grouped[aisle];
    const rackKeys = Object.keys(racks).sort(byText);
    const y = startY + aisleIndex * rowGap;

    rackRows.push(`
      <div class="aisle-label" style="left: ${112 + aisleIndex * 8}px; top: ${y + 48}px;">
        AISLE ${safeText(aisle)}
      </div>
    `);

    rackKeys.forEach((rack, rackIndex) => {
      const rackLocations = racks[rack].slice().sort((a, b) => {
        const shelfCompare = byText(a.shelfCode, b.shelfCode);
        if (shelfCompare !== 0) return shelfCompare;
        return byText(a.binCode, b.binCode);
      });

      const x = 120 + rackIndex * 245;

      rackRows.push(`
        <div class="rack-row" style="left: ${x}px; top: ${y}px;">
          ${rackLocations.map(loc => {
            const id = Number(loc.locationId || loc.id || 0);
            const cls = statusClass(loc);
            const selected = id === Number(selectedId) ? "selected" : "";

            return `
              <div class="bin2d ${cls} ${selected}" data-location-id="${id}" title="${safeText(loc.locationName)}">
                <div class="bin-code">${safeText(loc.locationCode)}</div>
                <div class="bin-capacity">${safeText(loc.capacityPercent || 0)}%</div>
              </div>
            `;
          }).join("")}
        </div>
      `);
    });
  });

  floor.innerHTML = `
    <div class="zone-label">Warehouse Layout</div>

    ${receiving ? `
      <div class="dock"
           style="top: 70px; width: 82px;"
           data-location-id="${Number(receiving.locationId || receiving.id || 0)}">
        Receiving
      </div>
    ` : ""}

    ${shipping ? `
      <div class="dock shipping"
           style="top: 150px; width: 82px;"
           data-location-id="${Number(shipping.locationId || shipping.id || 0)}">
        Shipping
      </div>
    ` : ""}

    ${rackRows.join("")}
  `;
}

function render3d(locations, selectedId) {
  const floor = document.getElementById("floor3d");

  if (!locations.length) {
    floor.innerHTML = `<div class="empty-state">3D preview will appear after locations are created.</div>`;
    return;
  }

  const rackGroups = {};

  locations.forEach(loc => {
    const key = `${loc.aisleCode || loc.zoneCode || "AREA"}-${loc.rackCode || loc.locationType || "RACK"}`;
    rackGroups[key] = rackGroups[key] || [];
    rackGroups[key].push(loc);
  });

  const racks = Object.keys(rackGroups).sort(byText).slice(0, 18);

  floor.innerHTML = `
    <div class="scene3d">
      <div class="floor-plane"></div>
      ${racks.map((key, index) => {
        const group = rackGroups[key];
        const first = group[0] || {};
        const id = Number(first.locationId || first.id || 0);
        const avgCapacity =
          group.reduce((sum, loc) => sum + Number(loc.capacityPercent || 0), 0) / Math.max(group.length, 1);

        const hasProducts = group.some(loc => Number(loc.productCount || 0) > 0);
        const cls = avgCapacity >= 100 ? "full" : hasProducts ? "assigned" : "empty";

        const col = index % 6;
        const row = Math.floor(index / 6);
        const left = 38 + col * 62;
        const top = 34 + row * 92;

        return `
          <div class="rack3d ${cls} ${id === Number(selectedId) ? "selected" : ""}"
               data-location-id="${id}"
               title="${safeText(key)}"
               style="left:${left}px; top:${top}px;">
            <div class="top"></div>
            <div class="side"></div>
            <div class="front"></div>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function normalizeLocations(rawLocations) {
  return rawLocations.map(loc => ({
    ...loc,
    locationId: loc.locationId || loc.id,
    locationCode: loc.locationCode || loc.code,
    locationName: loc.locationName || loc.name,
    locationType: loc.locationType || loc.location_type,
    zoneCode: loc.zoneCode || loc.zone_code,
    aisleCode: loc.aisleCode || loc.aisle_code,
    rackCode: loc.rackCode || loc.rack_code,
    shelfCode: loc.shelfCode || loc.shelf_code,
    binCode: loc.binCode || loc.bin_code,
    productCount: loc.productCount || loc.product_count || 0,
    capacityPercent: loc.capacityPercent || loc.capacity_percent || 0
  }));
}

function render(model) {
  lastModel = model || {};

  const rawLocations = Array.isArray(lastModel.locations)
    ? lastModel.locations
    : [];

  lastLocations = normalizeLocations(rawLocations);

  const selectedId = selectedIdFromModel(lastModel);
  const selectedLocation = lastLocations.find(x => Number(x.locationId) === selectedId);

  document.getElementById("subtitle").innerText =
    `${lastLocations.length} location(s) loaded from MySQL`;

  document.getElementById("debugText").innerText =
    selectedId ? `Selected location ID: ${selectedId}` : "No location selected";

  setSelected(selectedLocation);
  render2d(lastLocations, selectedId);
  render3d(lastLocations, selectedId);
  bindClicks();
}

if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(() => {
    render(appsmith.model || {});
  });
}

if (window.appsmith && appsmith.onModelChange) {
  appsmith.onModelChange((model) => {
    render(model || {});
  });
}

setTimeout(() => {
  render(window.appsmith?.model || {});
}, 400);
